package db

import (
	"database/sql/driver"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

type DB = *gorm.DB

type JSONB map[string]interface{}

// Value Marshal
func (jsonField JSONB) Value() (driver.Value, error) {
	return json.Marshal(jsonField)
}

// Scan Unmarshal
func (jsonField *JSONB) Scan(value interface{}) error {
	data, ok := value.([]byte)
	if !ok {
		return errors.New("type assertion to []byte failed")
	}
	return json.Unmarshal(data, &jsonField)
}

var dbInstance *gorm.DB

func newConnection(host, user, password, dbname, port string) (*gorm.DB, error) {
	// https://github.com/go-gorm/postgres
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: fmt.Sprintf("postgres://%s:%s@%s:%s/%s?sslmode=disable", user, password, host, port, dbname),
	}), &gorm.Config{
		Logger: logger.Default,
	})

	if err != nil {
		return nil, err
	}

	db.AutoMigrate(&Report{}) // nolint:errcheck

	return db, nil
}

type Report struct {
	RepositoryURL  string `gorm:"primaryKey"`
	PublicCodeYAML *bool
	Result         JSONB `gorm:"type:jsonb"`

	CreatedAt time.Time
	UpdatedAt time.Time `gorm:"autoUpdateTime"`
}

func SaveReport(report Report, runDate time.Time) error {
	if dbInstance == nil {
		host := os.Getenv("POSTGRES_HOST")
		user := os.Getenv("POSTGRES_USER")
		password := os.Getenv("POSTGRES_PASSWORD")
		dbname := os.Getenv("POSTGRES_DB")
		port := os.Getenv("POSTGRES_PORT")

		var missing []string
		for name, value := range map[string]string{
			"POSTGRES_HOST":     host,
			"POSTGRES_USER":     user,
			"POSTGRES_PASSWORD": password,
			"POSTGRES_DB":       dbname,
			"POSTGRES_PORT":     port,
		} {
			if value == "" {
				missing = append(missing, name)
			}
		}
		if len(missing) > 0 {
			sort.Strings(missing)

			return fmt.Errorf(
				"can't save to the database: missing environment variables: %s (set SKIP_SAVE_TO_DATABASE=true to skip saving)",
				strings.Join(missing, ", "),
			)
		}

		db, err := newConnection(host, user, password, dbname, port)
